var i=`query-optimization`;var n=54;var s={en:[{id:`T054-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Query Optimization`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Transaction isolation defines which effects of concurrent transactions can become visible and which anomalies are permitted.`},{id:`B`,text:`Query optimization reduces database resource use and latency while preserving semantics.`},{id:`C`,text:`Optimistic concurrency checks whether data changed before committing; pessimistic locking reserves exclusive access earlier.`},{id:`D`,text:`Partitioning splits a dataset into manageable segments; sharding distributes segments across nodes.`}]},{id:`T054-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Query Optimization`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Choose a partition key based on access patterns, distribution and growth.`},{id:`B`,text:`1NF uses atomic values in the chosen relational model; 2NF removes partial dependency on a candidate key; 3NF removes problematic transitive dependencies; BCNF tightens determinants; 4NF addresses independent multivalued dependencies; 5NF addresses certain join dependencies.`},{id:`C`,text:`Study B-tree, hash, full-text and specialized spatial or column indexes.`},{id:`D`,text:`Use EXPLAIN and measured traces; identify full scans, expensive sorts, N+1 ORM queries and unnecessary columns.`}]},{id:`T054-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A guest list page issuing one query per booking can be changed to a batched join or prefetch.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Large tenants can still create hotspots, so test whether tenant-only routing remains balanced as customers grow.`},{id:`B`,text:`Both can be implemented with several database engines depending on needs.`},{id:`C`,text:`Verify that pagination and permissions still behave correctly after the change.`},{id:`D`,text:`Recompute aggregates when reconciliation detects drift.`}]},{id:`T054-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Query Optimization`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Retrying every optimistic conflict can overwrite user intention; holding a pessimistic lock across network calls creates contention.`},{id:`B`,text:`Normalization can increase joins, while historical snapshots may intentionally duplicate data.`},{id:`C`,text:`Faster SQL can accidentally alter duplicates, ordering or transaction semantics.`},{id:`D`,text:`Duplicate fields can become contradictory under concurrency or missed events.`}]},{id:`T054-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It requires understanding actual query plans, cardinality estimates and access patterns rather than relying only on prettier SQL.`}]}]},{id:`T054-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`A query is optimized once it runs quickly on a tiny development database.`}]}]},{id:`T054-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`A cache may conceal bad plans; test at expected production scale rather than on ten rows.`}]}]},{id:`T054-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Query Optimization`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Use EXPLAIN and measured traces; identify full scans, expensive sorts, N+1 ORM queries and unnecessary columns.`},{id:`B`,text:`Read committed isolation prevents every anomaly under concurrent transactions.`},{id:`C`,text:`Query optimization reduces database resource use and latency while preserving semantics.`},{id:`D`,text:`Estimated query plans can replace measurements on representative data entirely.`}]},{id:`T054-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Query Optimization`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`An unused index has no storage cost and never slows inserts.`},{id:`B`,text:`A cache may conceal bad plans; test at expected production scale rather than on ten rows.`},{id:`C`,text:`Verify that pagination and permissions still behave correctly after the change.`},{id:`D`,text:`A query is optimized once it runs quickly on a tiny development database.`}]},{id:`T054-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A guest list page issuing one query per booking can be changed to a batched join or prefetch.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to optimize a slow product page using a derived rating count. Define update semantics, rebuild procedure and tests for duplicate or delayed events.`},{id:`B`,text:`Ask an agent to identify dependencies and anomalies in an order spreadsheet, normalize through 3NF, and explain where further normalization or intentional snapshots make sense.`},{id:`C`,text:`Have an agent implement both version-based updates and a locked allocation path. Load-test conflicts, deadlocks and user-facing resolution flows.`},{id:`D`,text:`Have an agent benchmark a slow reservation report, submit before/after plans and row counts, and add tests protecting output semantics.`}]},{id:`T054-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`What evidence proves the bottleneck is in the database rather than network or serialization?`}]}]},{id:`T054-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A guest list page issuing one query per booking can be changed to a batched join or prefetch.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Query Optimization`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T054-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A guest list page issuing one query per booking can be changed to a batched join or prefetch.`,b:!0},{t:` — propose three checks for `},{t:`Query Optimization`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T054-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A guest list page issuing one query per booking can be changed to a batched join or prefetch.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T054-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Query Optimization`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A guest list page issuing one query per booking can be changed to a batched join or prefetch.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T054-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Оптимізація запитів`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Ізоляція транзакцій визначає, які ефекти паралельних операцій видимі й які аномалії допустимі.`},{id:`B`,text:`Оптимізація запитів зменшує ресурси й затримку БД, зберігаючи семантику.`},{id:`C`,text:`Оптимістичний контроль перевіряє, чи змінилися дані перед фіксацією; песимістичне блокування завчасно резервує доступ.`},{id:`D`,text:`Партиціювання ділить дані на керовані сегменти; шардінг розподіляє їх між вузлами.`}]},{id:`T054-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Оптимізація запитів`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Оберіть ключ за шаблонами доступу, розподілом і зростанням.`},{id:`B`,text:`1NF вимагає атомарних значень у вибраній реляційній моделі; 2NF прибирає часткову залежність від ключа; 3NF — проблемні транзитивні залежності; BCNF посилює вимоги до детермінантів; 4NF враховує незалежні багатозначні залежності; 5NF — залежності з’єднання.`},{id:`C`,text:`Вивчайте B-tree, hash, full-text та спеціальні просторові/колонкові індекси.`},{id:`D`,text:`Використовуйте EXPLAIN та виміряні трасування; знаходьте full scan, дорогі sort, N+1 ORM-запити й зайві колонки.`}]},{id:`T054-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Сторінка гостей із додатковим запитом на кожне бронювання може перейти на batch join або prefetch.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Але великі орендарі утворюють hotspots, тому перевіряйте балансування в міру зростання.`},{id:`B`,text:`Обидва сценарії можна реалізувати різними СУБД залежно від деталей.`},{id:`C`,text:`Після зміни перевірте пагінацію та права доступу.`},{id:`D`,text:`Звірка виправляє розбіжності.`}]},{id:`T054-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Оптимізація запитів`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Автоматичний повтор кожного конфлікту може затерти намір користувача; утримання lock під час мережевого виклику створює конкуренцію.`},{id:`B`,text:`Нормалізація може збільшити кількість JOIN; історичні snapshots іноді свідомо дублюють дані.`},{id:`C`,text:`Швидший SQL може випадково змінити дублікати, порядок або транзакційну семантику.`},{id:`D`,text:`Дублікати полів можуть розходитися за конкуренції або втрати подій.`}]},{id:`T054-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Потрібно розуміти реальні плани виконання, оцінки кардинальності й шаблони доступу, а не лише «красивий SQL».`}]}]},{id:`T054-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Запит оптимізовано, якщо він швидко працює на малій тестовій БД.`}]}]},{id:`T054-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Кеш приховує погані плани; тестуйте на обсягах production, а не на десяти рядках.`}]}]},{id:`T054-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Оптимізація запитів`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Використовуйте EXPLAIN та виміряні трасування; знаходьте full scan, дорогі sort, N+1 ORM-запити й зайві колонки.`},{id:`B`,text:`Ізоляція Read Committed запобігає всім аномаліям конкурентних транзакцій.`},{id:`C`,text:`Оптимізація запитів зменшує ресурси й затримку БД, зберігаючи семантику.`},{id:`D`,text:`Оцінкові плани запитів повністю замінюють вимірювання на реальних даних.`}]},{id:`T054-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Оптимізація запитів`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Невикористаний індекс не займає пам’яті й не сповільнює вставки.`},{id:`B`,text:`Кеш приховує погані плани; тестуйте на обсягах production, а не на десяти рядках.`},{id:`C`,text:`Після зміни перевірте пагінацію та права доступу.`},{id:`D`,text:`Запит оптимізовано, якщо він швидко працює на малій тестовій БД.`}]},{id:`T054-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Сторінка гостей із додатковим запитом на кожне бронювання може перейти на batch join або prefetch.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента оптимізувати сторінку товару похідною кількістю оцінок. Визначте семантику оновлення, відновлення та тести повторених чи затриманих подій.`},{id:`B`,text:`Попросіть агента знайти залежності та аномалії в таблиці замовлень, нормалізувати до 3NF і пояснити, де потрібна подальша нормалізація чи історичний snapshot.`},{id:`C`,text:`Попросіть агента реалізувати оновлення за версією та бронювання з блокуванням. Перевірте конфлікти, deadlock і спосіб розв’язання для користувача.`},{id:`D`,text:`Попросіть агента заміряти повільний звіт, показати плани до/після й кількості рядків та додати тести незмінності результату.`}]},{id:`T054-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Які факти доводять, що вузьке місце в БД, а не в мережі чи серіалізації?`}]}]},{id:`T054-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Сторінка гостей із додатковим запитом на кожне бронювання може перейти на batch join або prefetch.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Оптимізація запитів`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T054-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Сторінка гостей із додатковим запитом на кожне бронювання може перейти на batch join або prefetch.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Оптимізація запитів`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T054-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Сторінка гостей із додатковим запитом на кожне бронювання може перейти на batch join або prefetch.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T054-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Оптимізація запитів`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Сторінка гостей із додатковим запитом на кожне бронювання може перейти на batch join або prefetch.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var a={slug:i,topicId:54,questions:s};export{a as default,s as questions,i as slug,n as topicId};